function tel(n){return 'tel:+1'+n;}
function el(t,c,h){var e=document.createElement(t);if(c)e.className=c;if(h!=null)e.innerHTML=h;return e;}
function parseSource(src){var _h=src.querySelector('h2');if(_h&&_h.parentElement){src=_h.parentElement;}while(src.children&&src.children.length===1&&src.children[0].querySelector&&src.children[0].querySelector('h2')){src=src.children[0];}var nodes=[].slice.call(src.childNodes),pre=[],secs=[],cur=null;
 nodes.forEach(function(n){if(n.nodeType===1&&n.tagName==='H2'){cur={title:n.textContent.trim(),html:''};secs.push(cur);}
 else{var h=n.nodeType===1?n.outerHTML:(n.textContent.trim()?'<p>'+n.textContent+'</p>':'');if(!h)return;if(cur)cur.html+=h;else pre.push(h);}});
 return {preamble:pre.join(''),sections:secs};}
function cleanProse(html){var d=el('div',null,html);
 d.innerHTML=d.innerHTML.replace(/<strong>\s*→?\s*Join the list[^<]*<\/strong>/gi,'').replace(/→\s*Join the list[^<]*?store opens\.?/gi,'').replace(/\s*\(see the banner( below)?\)/gi,'').replace(/↗/g,'');
 [].slice.call(d.querySelectorAll('p')).forEach(function(p){p.innerHTML=p.innerHTML.replace(/^\s*<strong>\s*Flow\s*&amp;\s*conditions[^<]*<\/strong>\s*/i,'').replace(/^\s*(<br\s*\/?>)?\s*-\s*/i,'');});
 [].slice.call(d.querySelectorAll('p')).forEach(function(p){var t=p.textContent.trim().toLowerCase().replace(/^[^a-z0-9]+/,'');
  var res=/(tva\.com|usace|lrn-wc|tn\.gov|nps\.gov|gooutdoorstennessee|ncwildlife|waterdata|usgs\.gov)/.test(t)||/\(tap to (call|dial)\)/.test(t)||/lake info line/.test(t);
  var stg=t.indexOf('official links')===0||t.indexOf('official resources')===0||t.indexOf('live conditions')===0||t.indexOf('gold permit banner')===0||t.indexOf('check the release')===0||t.indexOf('city permit required')===0||t.indexOf('permit required')===0;
  if(res||stg||t.length===0)p.remove();});
 return d.innerHTML;}
var KEY=function(t){t=t.toLowerCase();if(t.indexOf('overview')===0)return'overview';if(t.indexOf('flow')===0)return'flow';if(t.indexOf('reg')===0)return'regs';if(t.indexOf('conserve')===0)return'conserve';if(t.indexOf('access')===0)return'access';if(t.indexOf('hatch')===0)return'hatches';if(t.indexOf('field')===0)return'field';if(t.indexOf('faq')===0)return'faq';return t;};
var LABEL={overview:'Overview',access:'Access',flow:'Flow',hatches:'Hatches',field:'Field',regs:'Regs',conserve:'Conserve'};
var ORDER_SEC=['overview','access','flow','hatches','field','regs','conserve'];
var FREE={overview:1,flow:1,regs:1,conserve:1};
var ACCESS={"clinch-river":{"boundary":"About thirteen miles of trout water, from the base of Norris Dam down to the Highway 61 bridge at Clinton — a few minutes off I-75 northwest of Knoxville, in Anderson & Union Counties. Below the bridge it slides into the backwaters of Melton Hill Lake and the cold gives out.","points":[{"n":"The foot of the dam — TVA's Norris Dam area","d":"A paved drive on the west bank drops to the tailrace picnic area, with the River Bluff Trail working the shoreline downstream — the classic first look at the river, and the water people walk to when the horn is quiet."},{"n":"Songbird","d":"A canoe-and-walk-in access on the east side near the dam — nearly a mile of shoreline and the shallow, even gravel that makes for the friendliest wading on the river when nothing is running."},{"n":"The Weir","d":"About two miles down, the regulating weir splits the river around an island; the long flat above it and the broken riffles below are among the most-fished, most productive water on the Clinch — and the weir itself is the structure that made the fishery."},{"n":"Miller's Island","d":"A mile below the weir on the east shore — a paved ramp and the single most popular access on the river, prime wading at low water, and the reach that gave up the 28-pound-12-ounce state-record brown in 1988 that still stands."},{"n":"Massengill Bridge","d":"Turnouts and streamside trails a little farther down; workable water that draws a crowd when the river is up."},{"n":"Peach Orchard","d":"A shore-and-wade access off Highway 61 in the middle river — less pressure, honest water."},{"n":"The Jail / Llewellyn Island","d":"The streamside anglers' trail just above the Highway 61 bridge at Clinton — slow, clear flats long known for scud and midge fishing, and a good bet when the upper river is crowded."},{"n":"The Highway 61 bridge","d":"The boat ramp at Clinton and the bottom of the trout water; Eagle Bend sits just below, already lake water — too deep and warm to wade."}],"wf":"The upper accesses — Songbird, the Weir, Miller's Island — are the wading heart of the river when no units are running; from Miller's on down the Clinch fishes increasingly as a float. Which ramps pair for a given day's flow, and how to time a take-out against a generation pulse, is where this stops being free.","note":"A named access is not a safe wade — that depends entirely on generation. See Flow & Conditions before every trip."}};
Object.assign(ACCESS,{"boone-tailwater":{"boundary":"A few miles of cold tailwater on the South Fork Holston, from Boone Dam down to the Louis Milhorn Bridge on Beulah Church Drive, where the moving water gives way to the still upper end of Fort Patrick Henry Lake. It straddles Sullivan and Washington Counties in the Tri-Cities.","points":[{"n":"Boone Dam / TVA recreation area","d":"The recreation area at the base of the dam is the dependable anchor and holds the coldest, most oxygenated water — the best trout holding on the reach."},{"n":"Louis Milhorn Bridge","d":"The lower end of the trout water on Beulah Church Drive, where the river slows into Fort Patrick Henry Lake."}],"wf":"A short reach best waded near the dam when no units are running; floating from the dam down to the bridge is generation-dependent.","note":"This is a three-unit working tailwater — named access near the dam is not a safe wade when generating; the pulse travels downstream, water near the dam rising first. Check the Boone generation schedule before every trip."},"caney-fork-river":{"boundary":"Roughly twenty-six miles of tailwater below Center Hill Dam, running through DeKalb, Putnam and Smith Counties to the Cumberland near Carthage; the strongest trout water is the upper sixteen miles or so below the dam.","points":[{"n":"Center Hill Dam / Below the Dam","d":"The head of the fishery, where cold water is released from deep in Center Hill Lake — the signature reach and coldest, surest trout water."},{"n":"Long Branch","d":"Part of the signature upper reach just below the dam, paired with the dam water itself."},{"n":"Betty's Island","d":"A named mid-river landmark on the run from the dam down toward the lower river."},{"n":"Gordonsville (Stonewall) reach","d":"The warmed lower reach that TWRA stopped stocking because it became too warm for trout — orientation to where the trout water ends, not a trout destination."}],"wf":"Wade only on minimum or no generation; float on no-to-moderate flows, with heavy generation reserved for capable motorized boats.","note":"A Corps generation-driven tailwater — named access is not a safe wade during a release; cold water rises fast and reaches downstream stations with little local warning. Check the Center Hill generation schedule before every trip."},"fort-patrick-henry":{"boundary":"A short urban reach of the South Fork Holston below Fort Patrick Henry Dam, running about eight miles through Kingsport, past Long Island of the Holston, to the confluence with the North Fork Holston, in Sullivan County.","points":[{"n":"Fort Patrick Henry Dam (base of dam)","d":"The cool, oxygenated water at the foot of the dam — the best trout holding on the reach, especially behind a spring stocking."},{"n":"Long Island of the Holston","d":"The long river island just below the dam — the historical heart of the valley, sacred Cherokee treaty ground restored in part to the Eastern Band, with its own access limits."},{"n":"North Fork Holston confluence","d":"The downstream end of the reach, where the river warms and slows and the two forks join to form the Holston proper."}],"wf":"Wade near the dam when no units are generating; this is a short, part-private urban reach fished mostly on foot near the dam.","note":"Even this run-of-river dam lifts and quickens the reach when its two units run — named access near the dam is not a safe wade during a release; cold, quick water over slick urban rock, riprap and bridge structure is the real hazard. Check the generation schedule before every trip."},"hiwassee-river":{"boundary":"Some twenty miles of tailwater beginning at the Apalachia Powerhouse (not the dam eight miles east) in the Cherokee National Forest, Polk County; the first twelve miles — powerhouse to the US-411 bridge — are the trout section, split into the upper six (powerhouse to Reliance) and middle six (Reliance to US-411).","points":[{"n":"Apalachia Powerhouse / Powerhouse Boat Ramp","d":"Where the tailwater actually begins — cold, oxygen-rich water emerging from the mountain tunnel; the top of the stocked water and a launch with a day-use fee."},{"n":"L&N Railroad Bridge at Reliance","d":"The lower end of the stocked upper section and the divide between the upper and middle six miles."},{"n":"John Muir Gorge (Big Bend to Childers Creek)","d":"The roadless upper gorge, the finest water on the river, reachable only on foot by the John Muir Trail (#152)."},{"n":"US-411 bridge","d":"The downstream boundary of the trout section, at the bottom of the middle six miles."},{"n":"Towee launch","d":"A launch with a day-use fee downstream of the powerhouse; the Towee Creek confluence is a named landmark."},{"n":"Gee Creek take-out","d":"The lower take-out on the numbered float sequence from the powerhouse down."}],"wf":"Wade the main stem only when the powerhouse is not generating; float-and-shuttle logistics run from the powerhouse down, and the roadless gorge is foot access only.","note":"A working tailwater that has taken lives — named access is not a safe wade once a unit comes on; the release turns a wadeable flat into an impassable torrent in about two and a half to three hours, and the gorge has no cell service and few exits. Check the Apalachia generation schedule before every trip."},"holston-river-cherokee":{"boundary":"The cold upper reach of the Cherokee tailwater holds trout for roughly the first twenty miles below Cherokee Dam near Jefferson City; the fifty-mile river runs on toward the French Broad at Knoxville, with the lower thirty-odd miles warming into smallmouth country, in Jefferson and Grainger Counties.","points":[{"n":"Cherokee Dam ramp","d":"One of the three public ramps on the trout water and the top of the reach, at the head of the cold, surest trout fishing."},{"n":"Combs Shoals","d":"The cold shoals immediately below the dam — the coldest, surest trout water and one of only two genuinely worthwhile wade spots."},{"n":"Indian Cave ramp","d":"A middle public boat ramp; TWRA's original 1999 stocking ran from the dam down to the Indian Cave community."},{"n":"Nance's Ferry","d":"The lowest of the three ramps, whose surrounding riffles are the other genuinely worthwhile wade spot."}],"wf":"Wade the shoals only at low flow — genuinely worthwhile wading is limited to Combs Shoals below the dam and the riffles at Nance's Ferry; most of the river between the three ramps is private and fished by boat, often needing a small registered motor on the long flats.","note":"Cherokee can release in excess of sixteen thousand cfs; named access is not a safe wade during a release. Below the dam at Combs Shoals the rise arrives within minutes while lower accesses feel it hours later, and in minimum-flow periods the dam pulses roughly every five hours. Check the Cherokee generation schedule before every trip."},"obey-river":{"boundary":"About seven miles of tailwater below Dale Hollow Dam, from the dam and the National Fish Hatchery down to the river's mouth at the Cumberland near Celina, in Clay County; the best trout water is the upper reach near the dam and hatchery, warming toward the confluence.","points":[{"n":"Dale Hollow Dam / Corps and hatchery ground","d":"The top of the fishery, with generous public bank and parking on the Corps and hatchery ground below the dam and the coldest water near the dam."},{"n":"Dale Hollow National Fish Hatchery","d":"The federal hatchery on the tailwater's own bank — the reason the river fishes as it does, and the signature reach; worth a visit in its own right."},{"n":"Celina (river mouth at the Cumberland)","d":"The downstream end of the float, where the trout water gives way to warmwater fish near the Cumberland confluence."}],"wf":"A float-first river: plenty of public bank and parking below the dam and hatchery and some wadeable near-dam water at zero generation, but genuine wadeable water is thin — the working way to fish the less-pressured river is to drift toward Celina.","note":"A working Corps tailwater and a small one — named access is not a safe wade during a release; three units can turn a wadeable river to heavy current fast in the narrow channel. Check the Corps' Dale Hollow generation schedule (coordinated with the Southeastern Power Administration — there is no TVA line) before every trip."},"ocoee-river":{"boundary":"The Lower Ocoee tailwater below Ocoee Dam No. 1 (Parksville Dam), running from the dam down to the Hiwassee near Benton, in Polk County; the stocked trout water is the reach immediately below the dam.","points":[{"n":"Ocoee Dam No. 1 (Parksville) ramp","d":"The signature reach and the stocked water — the Lower Ocoee immediately below the dam, with a boat ramp and free parking."},{"n":"US-64 Ocoee Scenic Byway pull-offs","d":"Highway pull-offs along the byway that runs the gorge beside the river."},{"n":"Cherokee National Forest recreation areas on Parksville","d":"Forest Service recreation areas on Parksville (Lake Ocoee) above the dam."},{"n":"Ocoee–Hiwassee confluence","d":"The downstream end of the reach, where the Lower Ocoee joins the Hiwassee near Benton."}],"wf":"Wade the pool-and-pocket water only in confirmed off-water windows; when a release is on, the river belongs to the rafts and is dangerous whitewater, not a wading river.","note":"The most schedule-bound water in the series — the constraint is temporal, not spatial: a scheduled release turns a wadeable stream into heavy whitewater in minutes, on purpose. Named access is fishable only in confirmed off-water blocks, with a wide margin to be out before the water is due. Confirm the TVA Ocoee release schedule before every trip."},"south-holston-river":{"boundary":"About fourteen miles of spring-creek-like tailwater from the base of South Holston Dam, southeast of Bristol, down to the head of Boone Lake at Bluff City, in Sullivan County. The regulated trout water runs from the dam to Boone, including Boone Reservoir up to the Highway 11E bridge on the Watauga arm.","points":[{"n":"Osceola Island / weir dam","d":"The aerating labyrinth weir about a mile to a mile-and-a-half below the dam, straddling Osceola Island — the signature reach and a genuinely public wade access where the river takes on current and life."},{"n":"Bluff City (head of Boone Lake)","d":"The downstream end of the tailwater, where the river slows into Boone Lake and adds warmwater company."},{"n":"Hickory Tree Bridge / Bottom Creek","d":"A named landmark reach — the spawning closure runs from Hickory Tree Bridge up to the Bottom Creek confluence, closed to all fishing Nov 1–Jan 31."},{"n":"Boy's Island / Weaver Pike Bridge","d":"A named landmark island — the first island below Weaver Pike Bridge — marking the lower end of the second spawning closure."},{"n":"Webb Road Bridge","d":"A named landmark bridge marking the upper end of the second spawning-closure reach."}],"wf":"Wade only at zero generation; much of the river runs between private banks, so a good day is planned around the handful of public accesses and the private-bank water is reached by boat.","note":"A single big generating unit means no gentle middle stage — named access is not a safe wade once the unit comes on; the river swings by roughly two thousand cfs within the travel time of the pulse. A horn sounds near the dam. Check the South Holston generation schedule before every trip."},"watauga-river":{"boundary":"About sixteen miles of steeper, freestone-character tailwater from Wilbur Dam, through Carter County and Elizabethton, to Boone Lake near Johnson City, where it meets the South Holston. (The cold water comes from Watauga Lake, but the river is released through Wilbur Dam just below.)","points":[{"n":"Wilbur Dam","d":"The top of the tailwater and a wade point, though wading room is limited and a small rapid forms below the outflow."},{"n":"Hunter Bridge","d":"One of the genuine wade points on the upper-to-middle river."},{"n":"Sycamore Shoals","d":"Elizabethton city water and a state historic site — the Overmountain Men muster ground — that today doubles as one of the river's better public accesses."},{"n":"Riverside Park","d":"Elizabethton city water and a wade access alongside Sycamore Shoals."},{"n":"Blevins Road access","d":"A wade access at the head of the Quality Trout Fishing Area."},{"n":"Stoney Creek confluence","d":"A named wade point where Stoney Creek meets the river."},{"n":"Smalling Bridge to CSX railroad bridges (Quality Trout Fishing Area)","d":"The special-regulation heart of the river — Smalling Bridge down about two and a half miles to the CSX railroad bridges — managed to grow big wild browns."}],"wf":"A float-first river with a short list of genuine wade points; wade only at low flow when Wilbur is off, and reach the rest by drift boat.","note":"Named access is not a safe wade during a release — read the Wilbur release, not the Watauga Lake level (the classic rookie mistake); the river is broad and pushy, the rock is notoriously slick, and it hides deep pockets. Some accesses were altered by the 2024 Helene flood, so confirm locally."}});
Object.assign(ACCESS,{"barren-fork-river":{"boundary":"A roughly twenty-three-mile Highland Rim freestone from where its North and South Prongs join near Trousdale, straight through downtown McMinnville, to its mouth on the Collins River less than five miles below town. Most of the fishing is the mainstem through and just below McMinnville.","points":[{"n":"Downtown dam wade access","d":"Wading at the foot of the old town dam, where the tailrace and pools concentrate stocked trout and gamefish — but keep well clear of the dam face."},{"n":"Riverfront Park","d":"An in-town park with a pier and greenway, putting much of the town water within a short walk."},{"n":"Pepper Branch Park","d":"A city park on the river, part of the parks-and-greenway system through McMinnville."},{"n":"Bridge Street ramp","d":"One of the TWRA boat-access sites in McMinnville."},{"n":"VFW take-out","d":"The downstream take-out on the Collins at the end of the roughly six-mile downtown float."},{"n":"TWRA boat-access sites","d":"Three maintained boat accesses in town make this a rare, genuinely public town river."}],"wf":"Among the gentlest waters in the series — easy wading at the town dam and easy paddling from the parks, plus a roughly six-mile downtown-to-VFW float to the Collins.","note":"Gentle, but still a freestone — it rises and muddies after hard rain (fish it as it drops and clears), and the downtown low-head dam hides a dangerous hydraulic, so fish the tailrace but keep well clear of the dam face."},"big-soddy-creek":{"boundary":"A sandstone gorge creek in the Big Soddy Creek Gulf preserve off Walden Ridge above Soddy-Daisy; the trout water is the gorge upstream of Back Valley Road, and below the road it is a warmwater creek running down to Chickamauga Lake.","points":[{"n":"Big Soddy Creek Gulf trailhead","d":"The single public trailhead into the preserve; the fishable trout water is one creek reached from here."},{"n":"Back Valley Road","d":"The lower boundary of the trout reach — the delayed-harvest water is upstream of the road."},{"n":"Lower flats (old railbed)","d":"The flatter lower water walked along the old railroad-and-mining grade."},{"n":"Board Camp confluence and blue hole","d":"About a mile up the trail — the signature reach where the tributary comes in at the swimming hole."},{"n":"Upper gorge","d":"The tighter water above the blue hole as the walls close in."}],"wf":"A single walk-in creek fished from one trailhead, waded in the cold season along the old railbed grade up into the gorge.","note":"A flashy plateau-edge gorge that rises fast after rain over slick sandstone; there is no usable live gauge, so read recent rain and the creek's visible stage and fish it as it drops and clears. It is a swimming preserve first, busy with families in the warm months."},"calfkiller-river":{"boundary":"A freestone tributary of the Caney Fork, about eighteen miles from the western edge of the Cumberland Plateau near Monterey down through Sparta to its mouth at the Caney Fork below town. Treat the cooler upper river as the trout water and the lower valley as the smallmouth stream.","points":[{"n":"The river through Sparta","d":"The signature valley reach through the county seat, reached off US-70 and TN-111."},{"n":"Public road crossings","d":"Access is by the public road crossings through Sparta and along the valley and plateau-edge corridor; much of the intervening bank is private farmland."},{"n":"Plateau edge near Monterey","d":"The cooler upper (Putnam County) reaches that receive the spring rainbow stockings."},{"n":"Mouth at the Caney Fork","d":"The downstream end of the reach-by-reach orientation, below Sparta."}],"wf":"A gentle valley river with no developed trout park or major ramp — wade-and-bank water over cobble and gravel, reached at the public road crossings.","note":"A freestone with no dam to steady it — it rises and muddies fast after hard rain, so read the stage and fish it as it drops and clears; mind slick limestone, undercut banks, and farm fencing. Much frontage is private, so confirming a legal public crossing is on the angler."},"citico-creek":{"boundary":"A wilderness freestone rising in the Citico Creek Wilderness off the Unicoi crest as two forks that join to form Citico Creek proper, running north along Forest Road 35-1 to the Little Tennessee River (Tellico Lake) near Vonore. The permit water runs from the Little Citico Creek confluence up to the North/South Fork confluence.","points":[{"n":"Forest Road 35-1 (Citico Creek Road)","d":"Follows the lower permit water and reaches the dispersed sites and the forks trailheads."},{"n":"Forest Road 2659 loop","d":"A rough 14-mile loop that opens more tributary water for high-clearance vehicles."},{"n":"TWRA Citico Check Station","d":"The check-in point on the way in for permit, regulation, and on-the-ground condition information."},{"n":"Little Citico Creek confluence","d":"The lower bound of the stocked permit water on the main branch."},{"n":"The high forks (protected)","d":"Above the forks confluence the North and South Forks are walk-in wilderness holding native Southern Appalachian brook trout — kept deliberately protected, with the pool-by-pool waypoints withheld."}],"wf":"Two creeks in one: a broad, road-followed lower permit creek you wade, and a tight, walk-in pocket-water wilderness in the forks above.","note":"A rain-fed freestone with no on-creek gauge that rises and muddies fast, in country far from help with no reliable cell signal — fish it as it drops and clears, know your exit before you wade, and never force a crossing on rising water."},"collins-river":{"boundary":"A Cumberland Plateau and Highland Rim freestone, about sixty-seven miles from its source near Palmer and the Savage Gulf gorge, out along State Route 56 past Beersheba Springs and northwest through Warren County past McMinnville, to its mouth at Rock Island on Great Falls Lake. Trout are the upper (Grundy County) reach; smallmouth and muskie the lower river.","points":[{"n":"Savage Gulf gorge","d":"The protected headwater reach in South Cumberland / Savage Gulf State Park — remote, rugged, steep-sided, reached on foot with no quick way out."},{"n":"Turners Bend","d":"A named public ramp on Myers Cove Road."},{"n":"SR 56 ramp","d":"A public ramp above the Warren–Grundy county line."},{"n":"VFW bridge ramp","d":"A public ramp on U.S. 70."},{"n":"Rock Island","d":"The protected lower bookend at the mouth on Great Falls Lake, just above Great Falls Dam."}],"wf":"The clear, shallow lower river wades with ordinary care and much of it is best fished from a small boat or kayak on point-to-point floats; the upper Savage Gulf gorge is remote walk-in country.","note":"A freestone with no dam to release on you, but it rises and muddies fast after rain, and the upper gorge is remote and unforgiving — read the stage and the recent rain, and know your exit. The navigable river is public but the intervening banks are largely private farmland."},"conasauga-river":{"boundary":"A dam-free mountain river rising near 3,600 feet in the Cohutta Wilderness on the Tennessee–Georgia line; the trout water is the roadless wilderness reach up top, and the accessible Tennessee water is in Polk County above the U.S. 411 bridge, a protected State Scenic River. The river crosses the state line more than once.","points":[{"n":"Blue Hole fish-viewing site","d":"A Forest Service fish-viewing site, home to a citizen snorkeling program in the famously clear water — a public point, not a trout access."},{"n":"Cohutta campgrounds","d":"Established Forest Service campgrounds ringing the wilderness on both sides of the state line."},{"n":"Conasauga River Trail corridor","d":"The marked trail corridor along the river, the way foot-access anglers travel the reach."},{"n":"U.S. 411 bridge","d":"The lower boundary of the Tennessee State Scenic River / Class I Natural Area reach in Polk County."}],"wf":"A do-it-yourself, foot-access wilderness fishery — walk-in only, with essentially no commercial guiding.","note":"No dam and no gauge on the reach, so there is no horn and no schedule — never wade what you cannot see the bottom of, watch for rising or coloring water and rain upstream, and get out early; much of the reach is far from any road or help, with no reliable cell coverage. The fragile native brook-trout headwaters are kept deliberately coarse."},"doe-river":{"boundary":"A freestone off Roan Mountain running north through Roan Mountain State Park and the town of Roan Mountain, down along U.S. 19E, threading the private Doe River Gorge below Hampton, to its mouth on the Watauga River near Elizabethton, all in Carter County.","points":[{"n":"Roan Mountain State Park","d":"The signature reach — a small, tightly canopied stream cool enough to hold wild trout, under a special catch-and-release regulation in the cold months."},{"n":"Doe River Fishing Trail","d":"A string of marked public parks and legal pull-offs along U.S. 19E, opened by Trout Unlimited volunteers in 2018 on a river otherwise hemmed by private land."},{"n":"Covered Bridge Park","d":"A public access in Elizabethton on the lower river."},{"n":"Doe River Gorge (closed)","d":"The gorge bottom is privately owned by an adventure camp and is not open to public fishing without permission — a thing to admire from its edges."}],"wf":"Wade the small, canopied park water and the medium brown-trout stream below it; use only the state park and the marked Fishing Trail accesses, as much of the river is private.","note":"A rain-fed freestone that rises and muddies fast and clears as it drops; the defining hazard here is land, not water — fish only the park and marked accesses, park legally along U.S. 19E, and treat the gorge as the private property it is. The native brook-trout headwaters are deliberately not mapped."},"gatlinburg-west-prong":{"boundary":"About three river miles of the West Prong of the Little Pigeon through the middle of Gatlinburg, from the Great Smoky Mountains National Park boundary at the Gatlinburg Trail trailhead at the south edge of town down to the Gatlinburg spur. A City of Gatlinburg permit is required year-round for ages 13–64.","points":[{"n":"Gatlinburg Trail trailhead","d":"The park boundary at the south edge of town, the upper end of the City-managed reach, where the river leaves the park."},{"n":"SkyLift core","d":"The downtown core, where the deepest, most-structured bridge pools and the water below the SkyLift hold the big holdover browns."},{"n":"Herbert Holt Park","d":"A stretch reserved and free for children 12 and under — the best place in town to start a kid on trout."},{"n":"Le Conte Creek","d":"A tributary through town, part of the same City-managed trout fishery."},{"n":"Gatlinburg spur (Welcome Center)","d":"The lower end of the City reach near the Welcome Center, where permits are sold and a park-and-ride trolley runs in."}],"wf":"Walk-up wade water on a gentle urban gradient — pocket water and long bridge pools fished mostly from gravel bars and bridge aprons, right beside River Road and the Parkway.","note":"A flashy, rain-fed freestone that can turn a shin-deep stream into a brown torrent in under an hour — watch the upstream weather and get off the moment it rises and clouds; mind the slick concrete aprons and check dams. A City of Gatlinburg permit is required year-round for ages 13–64."},"little-pigeon-river":{"boundary":"The freestone water outside the national park — the West Prong through Pigeon Forge and the main stem at and below Sevierville, at the Forks of the River where the West and East forks meet, all in Sevier County.","points":[{"n":"Patriot Park","d":"The upstream anchor in Pigeon Forge, beside the 1830 Old Mill at the head of the greenway."},{"n":"Riverwalk Greenway","d":"Four miles of riverside greenway through The Island, putting walk-up trout water within a short step of the water."},{"n":"The Island","d":"The City of Pigeon Forge releases its larger cold-month fish between Patriot Park and The Island."},{"n":"The Old Mill of Pigeon Forge","d":"An 1830 grist mill on a milldam impoundment of the West Prong, at the center of the in-town water."},{"n":"Sevierville City Park","d":"The main-stem anchor at Sevierville, with the West Prong Greenway running to the Forks of the River."}],"wf":"Exceptional, genuinely walk-up wade water off miles of greenway — but a real, rain-fed river, cold in the stocking season, with smallmouth on the lower main stem in the warm months.","note":"Flow rises and colors quickly after rain and city runoff, the rock and banks are slick, and the stocking season is cold-water season — wade conservatively when it's up and mind traffic at the busy road and bridge crossings. Parking is the limiting factor around The Island."},"little-sequatchie-river":{"boundary":"A cool valley freestone tributary of the Sequatchie River, from the toe of the Cumberland Plateau near Tracy City down the west side of the Sequatchie Valley to its mouth on the Sequatchie River near the community of Sequatchie, below Whitwell, in Marion and Sequatchie Counties.","points":[{"n":"Sequatchie Valley (TN-28) road crossings","d":"Access is by the public road crossings of the valley corridor and any public frontage along them; much of the intervening bank is private farmland."},{"n":"Lower valley and mouth","d":"The signature reach — the deep lower valley and the mouth on the Sequatchie River, thickest with warmwater fish."},{"n":"Plateau toe near Tracy City","d":"The cool upper reach off the Plateau's edge that holds the cool-season stocked rainbows."}],"wf":"Easy wade-and-bank water over valley cobble and gravel, with no developed boat ramp or river park.","note":"A rain-driven freestone that rises and muddies fast after hard rain — read the stage and fish it as it drops and clears; mind slick limestone, undercut banks, and farm fencing in rural country where help is not always close. Much of the bank is private farmland, so legal access is the angler's to confirm."},"rocky-river":{"boundary":"A Cumberland Plateau freestone tributary of the Caney Fork, gathering near Spencer in the Fall Creek Falls country and falling about seventeen miles down the Welchland valley to Great Falls Lake near Rock Island, in Van Buren/Warren Counties. Trout are the cool middle river; muskie and bass the lake embayment.","points":[{"n":"Welchland middle-river reach","d":"The signature stocked reach — the cool limestone middle valley where the cool-season rainbows go in."},{"n":"Mouth at Great Falls Lake","d":"The lower embayment near Rock Island, warmwater and muskie water fished by boat."},{"n":"Plateau descent and plateau head","d":"The steep upper river off the sandstone caprock near Spencer."},{"n":"Public road crossings and Great Falls Lake access","d":"The public way in — road crossings and the public lake access; much intervening bank is private."}],"wf":"Wade the cool limestone middle river; the steep upper water is rough plateau descent, and the lower Great Falls Lake embayment is open, boat-and-PFD water for smallmouth and muskie.","note":"A rain-fed freestone with no dam — but it rises hard and fast off the plateau after rain, so fish it as it drops and clears, stay off the steep upper river high, and wear a PFD on the open lake embayment. Much of the frontage is private."},"sequatchie-river":{"boundary":"A spring-born valley freestone running about 116 miles from the Head of the Sequatchie spring near Grassy Cove, down the Sequatchie Valley past Dunlap and Whitwell, to the Tennessee River near Jasper, through Cumberland, Bledsoe, Sequatchie, and Marion Counties.","points":[{"n":"Head of the Sequatchie spring","d":"The karst headspring at the base of Brady Mountain where the river emerges full-grown, protected with Devilstep Hollow Cave in Cumberland Trail State Park."},{"n":"Sequatchie River Blueway","d":"A designated network of public paddling launches the valley communities created to open access while keeping people off private farmland."},{"n":"Dunlap Blueway corridor","d":"The signature reach along the blueway near Dunlap."},{"n":"Ketner Mill Road access","d":"A river access near Whitwell — and the take-out above the deadly low-head dam just below it; a take-out, not a place to drift past."}],"wf":"Wade gravel and ledge at normal and low flows, but it is chiefly a classic plateau-valley smallmouth float between public and designated-blueway launches.","note":"A rain-fed freestone that floods hard; the most serious hazard is the marked low-head dam at Ketner's Mill near Whitwell, which has killed repeatedly — if you float the lower river, take out above it. Watch for strainers, blowdowns, and fences spanning the river."},"tellico-river":{"boundary":"A high-gradient Blue Ridge freestone rising above 2,800 feet near the Tennessee–North Carolina state line and falling through the Cherokee National Forest to Tellico Plains, in Monroe County. The catch-and-release reach runs from the North River mouth up to the state line; the Tellico–Citico permit water runs from the Turkey Creek confluence up to the state line.","points":[{"n":"River road (Cherokee National Forest)","d":"The public main-stem access runs reach by reach along the river road from the state line down to Tellico Plains."},{"n":"State-line plunge pool","d":"The signature reach at the top of the catch-and-release, artificial-only water near the state line."},{"n":"Bald River Falls confluence","d":"A signature roadside reach where the Bald River comes in; carry a wading staff in every section above here."},{"n":"Turkey Creek confluence","d":"The lower boundary of the permit water — below it, standard statewide trout regulations apply and no permit is required."},{"n":"TWRA hatchery reach","d":"Below the hatchery, stocked rainbows concentrate in the accessible roadside pools of the permit and lower water."},{"n":"Wild-trout tributaries (protected)","d":"The North River, Bald River, Sycamore Creek, and Rough Ridge Creek are named single-hook artificial-only wild-trout streams; the native brook water above their barriers is kept deliberately general."}],"wf":"Wade high-gradient boulder and pocket water roadside along the river road, broadening to slower, deeper browns water toward Tellico Plains; it asks a different question in every mile.","note":"A free-flowing freestone that can rise four to six feet in under an hour in a thunderstorm — most wading turns dangerous above about 500 cfs; check the USGS gauge before you wade, carry a staff above Bald River Falls, and get out at the first rise, cloud, or thunder."}});
Object.assign(ACCESS,{"beaverdam-creek":{"boundary":"A roadside mountain creek in Shady Valley running two fisheries back to back: a marked, unstocked, artificial-only trophy reach around Backbone Rock that grows wild stream-bred browns, and a stocked-rainbow reach below it down toward the Virginia line. It fishes year-round.","points":[{"n":"Backbone Rock Recreation Area","d":"The on-water base at the foot of the 1901 rail cut, and the pivot between the trophy water above and the stocked water below."},{"n":"Highway 133 pull-offs","d":"Roadside stocked-rainbow water that concentrates around the accessible pull-offs the highway follows."}],"wf":"Roadside wade water, fished a pocket and a pool at a time, with generally easy wading outside of high water.","note":"Rain- and spring-fed creek that rises after rain and runs alongside a close, curvy highway, so park fully off the pavement and cross with care."},"bill-creek":{"boundary":"A short, high, rhododendron-walled headwater on the Iron Mountain flank near Iron Mountain Gap, running its whole length above 3,100 feet and holding native Southern Appalachian brook trout in a small, recovering fishery.","points":[],"wf":"A small, thin, walk-in headwater fished a pocket at a time, wadeable only when low and clear.","note":"A fragile native-brook fishery in steep, remote country with unreliable-to-nonexistent cell; go in light, low, and rarely, and leave your plan and out-time. The upper brook reach is kept deliberately coarse and unmapped."},"brush-creek":{"boundary":"A small roadside mountain freestone off Paint Mountain dropping through the Cherokee National Forest to the French Broad near Del Rio, carrying a spring stocking of rainbows; the trout thin from the lower creek as summer warms it.","points":[{"n":"Forest Road 209 (Brush Creek Road)","d":"The road follows the creek most of its length, making access public and roadside."},{"n":"Mouth on the French Broad / lower stocked reach","d":"The lower put-and-take reach worked from the pull-offs where the stocked rainbows hold."},{"n":"Houston Valley Campground","d":"A developed Forest Service campground near the upper drivable end of the road."}],"wf":"Roadside wade for most of its length over slick boulder and bedrock; a small, steep freestone.","note":"A small, steep freestone that rises and colors fast after rain over slick rock, in bear country; cell coverage thins to nothing off the highway."},"buffalo-creek":{"boundary":"A cold limestone spring creek in the Buffalo Springs WMA. The open fishery runs from the mill dam downstream to the WMA boundary; everything above the mill dam (the springs and hatchery) is closed year-round.","points":[{"n":"The mill dam","d":"The open/closed line: fish only downstream of it, never above."},{"n":"The falls / plunge pool below the dam","d":"A deceptively deep pool that anchors the upper end of the open reach."},{"n":"The dirt-road corridor","d":"A half-mile road parallels the open reach down to the WMA boundary."},{"n":"Owl Hole Gap Road / Buffalo Creek Waterfalls parking","d":"The access spine off US-11W and the falls parking for the corridor walk-in."}],"wf":"A small, gentle creek you can wade in street shoes over gravel and cobble, no backcountry gear required.","note":"Honor the year-round closed reach above the mill dam; the falls plunge pool is deceptively deep with a fast entry current, and the farm watershed rises and muddies fast after rain."},"cane-creek":{"boundary":"A stocked rainbow creek inside Fall Creek Falls State Park, on the eastern top of the Cumberland Plateau. The trout reach is the gentler water around the George Hole down past the Newton Ford Bridge; the Cane Creek Cascades mark its downstream limit.","points":[{"n":"The George Hole","d":"A deep, slow pool that takes about three-quarters of each stocking."},{"n":"Newton Ford Bridge (Highway 284)","d":"Productive stocked water runs down past and well below the bridge."},{"n":"Cane Creek Cascades","d":"The downstream limit of the trout reach; below them is dangerous gorge ground, not fishing water."}],"wf":"An easy, friendly wade in normal flow, fished from the bank and by easy wading around the stocking sites.","note":"The real danger here is the park's scenery, not the creek: stay off the cascade lips and well back from the unfenced overlook edges and gorge, and treat every wet sandstone surface as a hazard."},"charles-creek":{"boundary":"A small Highland Rim creek of the Collins system, tributary to the Collins River just below (northeast of) McMinnville, stocked seasonally with rainbows and fished while the water stays cool. Low and gentle.","points":[{"n":"Mouth at the Collins below McMinnville","d":"The lower creek and mouth, where the Collins warmwater community begins."},{"n":"The middle farm reach","d":"A gentle stretch through private farmland."},{"n":"Cool headwaters toward the Cannon County line","d":"Shaded upper water that holds cool longest into summer."}],"wf":"Small, gentle, wadeable water, but much of it crosses private farmland where access must be earned by permission.","note":"Much of the creek crosses private ground, so ask permission and honor postings; watch slick limestone and undercut banks, and cell coverage in the rural draws is unreliable."},"coops-creek":{"boundary":"A steep escarpment creek that falls off the Cumberland Plateau to the Sequatchie River near Dunlap. The cold upper gorge is the trout's summer refuge; the lower valley reach is gentler, warmer, and turns to bass water in summer.","points":[{"n":"Mouth at the Sequatchie near Dunlap","d":"The gentle lower valley reach that warms and holds warmwater fish in summer."},{"n":"The cold escarpment gorge","d":"The steep, shaded upper water that stays cold and holds the trout in summer."},{"n":"The Plateau headwaters","d":"The top of the drainage, up on the Cumberland Plateau."}],"wf":"Wade the steep gorge only when it is low and clear, with great care and a partner; the valley reach is gentler but largely private.","note":"A steep, flashy gorge that rises hard and fast after rain over slick bedrock, plunge pools, and waterfalls; the gorge is remote and much of the valley reach is private land."},"gap-creek":{"boundary":"A small, roadside stocked stream that falls off Iron Mountain Gap on the Carter/Unicoi divide and runs northwest toward the Johnson City edge of Washington County. Convenience put-and-take water, best in the cooler months.","points":[{"n":"The lower creek at the Johnson City edge","d":"A settled, roadside corridor on the edge of the Tri-Cities with posted private land."},{"n":"The stocked mid reach","d":"The middle water where TWRA puts fish."},{"n":"The headwaters near Iron Mountain Gap","d":"Cooler, higher water that fishes better in warm weather."}],"wf":"Small, wadeable water when low or normal and clear; much of the lower corridor is settled and posted.","note":"Rain-fed water that comes up after rain; mind posted private land in the settled lower corridor, and don't count on a cell signal as you climb toward the gap."},"goforth-creek":{"boundary":"A small freestone that tumbles in cascades down the north wall of the Ocoee River Gorge to the Middle Ocoee, stocked with rainbows by TWRA in spring and reached from one pull-off on U.S. 64. A cool-season put-and-take creek.","points":[{"n":"Goforth Creek recreation area (U.S. 64)","d":"The single public pull-off and base on the Ocoee Scenic Byway."},{"n":"Lower cascades & rec-area plunge pools","d":"Near the mouth at the Middle Ocoee, where the stocked rainbows concentrate."},{"n":"The creekside trail (~3.7 miles)","d":"Climbs the gorge to smaller, cooler upper water."}],"wf":"A steep gorge creek walked and waded in the cool season when low and clear; wear studs or felt on the cascade rock.","note":"A steep gorge creek that floods fast after rain over slick bedrock and cascades; in warm months the plunge pools are busy swimming holes, and the byway in is narrow and rockslide-prone."},"goose-creek":{"boundary":"A small freestone in the Mountain City country of Johnson County, listed by TWRA as 'Goose Creek / Town Creek' and stocked with rainbows through spring. A put-and-take town creek, best in and just after the spring stocking window.","points":[{"n":"The stocked town reach","d":"The accessible Town Creek corridor through Mountain City where the truck reaches the water."},{"n":"The Town Creek confluence","d":"Below the stocked reach, where Goose Creek meets the Town Creek drainage."},{"n":"The cooler headwaters toward Iron Mountain","d":"Higher, cooler water climbing toward the ridge."}],"wf":"A small, easy wade over cobble and bedrock in normal flow, suitable for a careful beginner.","note":"This country took the brunt of the 2024 Helene flood, which rearranged banks and access, so verify access before you rely on it; the freestone rises and stains fast after rain."},"gulf-fork-big-creek":{"boundary":"A small rain-fed fork off the Tennessee flank of the Bald Mountains that joins Big Creek near Del Rio. The accessible lower and middle water is stocked rainbow; native Southern Appalachian brook trout hold the cold, barrier-protected headwaters above, which are kept off the map.","points":[{"n":"Martha Sundquist State Forest (the old 'Gulf Tract')","d":"Public lower-and-middle water reached up the Big Creek drainage, traced by a gravel forest road and the Tennessee Gulf Trail."},{"n":"The boulder staircase of the middle reach","d":"The signature accessible stocked water of the fork."}],"wf":"A walk-in freestone up a gravel forest road and creekside trail, waded in normal or low, clear flow with ordinary care.","note":"The native brook-trout headwaters are deliberately left off the map and protected voluntarily; the steep freestone rises fast over slick bedrock, cell coverage disappears once the pavement ends, and it's bear country."},"hampton-creek":{"boundary":"A small, cold cove creek that falls off the north flank of Roan Mountain through Hampton Creek Cove State Natural Area to the Doe River. Below a constructed barrier the lower creek holds wild rainbows and browns; above it the Left Prong and upper cove are native brook-trout water.","points":[{"n":"Hampton Creek Cove natural-area trailhead","d":"The one public gate off Hampton Creek Road near the town of Roan Mountain, with a gravel lot and trail map."},{"n":"The cove meadows and lower reach below the barrier","d":"General wild-trout water for rainbows and browns, from the Doe River mouth up to the barrier."}],"wf":"A small, high cove creek fished a pocket at a time, walked in from the trailhead.","note":"The native brook water above the barrier (the Left Prong and upper cove) is kept off the map by design; fish below the barrier freely, but this is high, cold, bear country with unreliable cell."},"horse-creek":{"boundary":"A small Bald Mountains freestone dropping through the Cherokee National Forest toward the Nolichucky near Greeneville. It stacks three reaches: a stocked family reach around the recreation area, a special-regulation wild-trout middle above it, and native brook trout up Squibb Creek in the Sampson Mountain Wilderness.","points":[{"n":"Horse Creek Recreation Area","d":"A Forest Service campground and day-use site; the stocked put-and-take family reach."},{"n":"The special-regulation middle","d":"From the Forest Service boundary up to the Squibb Creek junction; wild rainbow and brown, the best public water."}],"wf":"A pocket-and-pool wade; the lower rec-area water is accessible, the middle is wild, and you climb for cold water in summer heat.","note":"The native brook trout up Squibb Creek in the wilderness are kept deliberately general and unmapped; the steep freestone rises fast over slick rock, there's no cell up high in this bear sanctuary, and it's Helene-affected country where access is provisional."},"laurel-fork":{"boundary":"A small, fast pocket creek in Laurel Fork Gorge above Dennis Cove near Hampton, walked in along an old railway grade and the AT. A cable crossing splits it: below is stocked general-regulation water, above (to the Forest Service boundary) is regulated wild brown and rainbow water. Native brook trout hold the coldest uppermost headwaters.","points":[{"n":"Dennis Cove Recreation Area","d":"The one public trailhead off Dennis Cove Road at U.S. 321 in Hampton."},{"n":"The cable crossing","d":"A half-mile above Dennis Cove; the boundary between the stocked lower creek and the regulated wild water above."},{"n":"Laurel Fork Gorge (railway grade / AT)","d":"Walk-in wild-brown water strung the length of the gorge on foot trails."}],"wf":"Walk-in gorge pocket water fished upstream, with the trail fording the creek repeatedly deeper in.","note":"The native brook trout of the coldest headwaters are left undisturbed and unmapped; the flashy gorge rises fast after rain, the fords turn dangerous at high water, the rock is slick, and cell is thin to nil."},"little-stony-and-rough-ridge":{"boundary":"A pair of small, protected single-hook headwater creeks draining toward the Watauga Lake side of Carter County. Little Stony's special-regulation reach is upstream of the Plot Branch confluence (1.3 miles above the Highway 321 crossing); the upper Little Stony and Rough Ridge headwaters are documented native brook-trout restoration water.","points":[{"n":"The Little Stony mouth (Watauga Lake side)","d":"The lower, general-rule point near the lake."},{"n":"The Plot Branch confluence area","d":"Where the special-regulation reach begins, about 1.3 miles above the Highway 321 crossing."}],"wf":"Small, cold, tight pocket water fished a pocket at a time; wadeable only when low and clear.","note":"The native brook reach above Plot Branch and all of Rough Ridge Creek are kept off the map by design, so keep locations coarse; these rain-driven headwaters rise fast over slick rock and cell is unreliable."},"north-barren-fork-creek":{"boundary":"The small North Prong of the Barren Fork in the Highland Rim farm country near Centertown, west of McMinnville, spring-stocked with rainbows. It joins the South Prong to form the Barren Fork River; a distinct, smaller water from that river.","points":[{"n":"The confluence where the Barren Fork forms","d":"The lower point where the North Prong meets the South Prong; warmwater fish appear here."},{"n":"The gentle middle farm reach","d":"A nearly flat stretch through private farmland."},{"n":"The small upper headwater","d":"The short upper prong."}],"wf":"Small, gentle, nearly flat wadeable water, but much of the prong crosses private farmland where access must be earned.","note":"Much of the prong is private farmland, so ask permission and honor postings; it rises and muddies fast after rain over slick limestone, and coverage is unreliable in this rural country."},"north-chickamauga-gorge":{"boundary":"A deep sandstone gorge cut into Walden's Ridge north of Chattanooga, stocked with rainbows through the cool months (roughly November–May) and reverting to a warmwater creek in summer. The trout water is two reaches: the gorge reach up to just above the Blue Hole, and the roadside Thrasher Bridge site in Soddy-Daisy.","points":[{"n":"Montlake Road trailhead","d":"The main gorge access into the natural area (currently closed by the park improvement project)."},{"n":"The Blue Hole","d":"The upper bound of the primary stocked gorge water, about a mile up (also closed by the project)."},{"n":"Thrasher Bridge, Soddy-Daisy","d":"The traditional roadside valley stocking site, unaffected by the gorge closure."},{"n":"Barker Camp / Flipper Bend","d":"Limited alternate parking that remains during the closure."}],"wf":"A gorge creek fished at a creek's scale, waded with care when clear and normal; the deep blue holes are not wade-and-cross water.","note":"Since about March 2026 the Montlake entrance, main trailhead, and Blue Hole are closed into ~2027, so confirm status and keep a backup water; the flashy gorge rises fast, the park posts color-coded creek closures, and cell fails in the canyon."},"north-indian-creek":{"boundary":"A limestone spring creek in the Limestone Cove of Unicoi County running down the TN 107 valley to the Nolichucky near Erwin. Most of its length is private; the dependable public water is the Forest Service Limestone Cove day-use reach.","points":[{"n":"Limestone Cove day-use reach","d":"The dependable public water and the creek at its best, cool forested cove off TN 107."},{"n":"TN 107 corridor","d":"A ribbon of alternating public and private water along the valley road."},{"n":"Nolichucky mouth near Erwin","d":"Where the warm valley reaches grade into the Nolichucky bottomland."}],"wf":"A small, gentle wade over slick limestone, mostly roadside from the day-use reach.","note":"The property line governs the day here: fish only the marked public boundaries, and the creek rises and clears fast after rain with no governing gauge on the fished reach."},"paint-creek":{"boundary":"A Cherokee National Forest freestone in Greene County, with Forest Road 41 following about five miles from the Forest Service campground down to the French Broad. The campground splits stocked lower water from quieter wild water above.","points":[{"n":"Forest Service campground (the hinge)","d":"The dividing line between the stocked lower corridor and the wild upper reach."},{"n":"Forest Road 41 corridor","d":"The road that parallels the creek and makes the lower water easy to reach."},{"n":"Upper wild reach","d":"Quieter wild-trout pocket water under stricter rules, reached by the Paint Creek and Little Paint Creek trails."},{"n":"Roadside cascade and plunge pool","d":"A signature cascade with a plunge pool known for surprisingly large rainbows."},{"n":"Lower corridor to the French Broad","d":"The overlooked lower water down to the river mouth near Paint Rock."}],"wf":"A small, wadeable creek at normal flows; roadside access along the lower corridor, walk-in on the upper reach.","note":"A free-flowing freestone that comes up hard and fast after rain; this is heavily used bear country with mandatory food storage, and the upper reach is steep and remote."},"panther-creek":{"boundary":"A small, seasonally stocked creek running through Panther Creek State Park on the Morristown shore of Cherokee Lake, from its stocked stretch down to the boat-ramp cove where it meets the lake.","points":[{"n":"Panther Creek State Park","d":"The gated, mapped state park through which the whole fishery is reached."},{"n":"Information kiosk and trail hub","d":"The park's signed orientation point and trail junction."},{"n":"Campground","d":"The stocked fished reach runs alongside the campground."},{"n":"Cherokee Lake boat ramp","d":"The ramp in the cove where the creek meets the lake."}],"wf":"An easy, low-gradient wade in normal flow, a short walk from the parking lot; much of it fishable from developed park shoreline.","note":"The water is genuinely cold in the trout season, and the park warns that rock ledges at the Cherokee Lake margin near the mouth can give way without warning."},"piney-creek":{"boundary":"A Cumberland Plateau gorge stream (the Piney River) in Rhea County near Spring City, running through Justin P. Wilson Cumberland Trail State Park. The stocked reach runs from the state-park land down to the Highway 27 bridge.","points":[{"n":"Piney River Picnic Area and trailhead","d":"The main access and northern terminus of the Cumberland Trail's Piney River Segment."},{"n":"Newby Branch trailhead","d":"The far-end trailhead of the roughly seven-mile out-and-back gorge trail."}],"wf":"Wadeable when cold, low, and clear; a steep gorge fished largely by walking in on the Cumberland Trail.","note":"A steep gorge freestone that rises fast after rain over slick rock and falls just as quickly; cell coverage in the gorge is unreliable."},"pistol-creek":{"boundary":"An urban creek dammed into Greenbelt Lake in Bicentennial Greenbelt Park in downtown Maryville. The regulated water is Greenbelt Lake plus Pistol Creek from East Harper Avenue upstream to West Lamar Alexander Parkway.","points":[{"n":"Bicentennial Greenbelt Park","d":"The downtown park that is the whole fishable water, with parking steps away."},{"n":"Greenbelt Lake","d":"The main stocking water, a shallow urban pond held by a low dam."},{"n":"Dam and spillway pool","d":"One of the two ends that hold the most fish, and a real hazard."},{"n":"Inlet where Pistol and Brown Creeks come in","d":"The other fish-holding end of the lake."},{"n":"Greenway corridor and creek pockets","d":"Creek pockets along the nine-mile paved Maryville–Alcoa Greenway."}],"wf":"Mostly bank or paved-greenway-edge fishing; wading, where it happens, is ankle-to-knee in the shallow creek.","note":"This is a winter fishery — cold-water immersion and the slick lake spillway are the two hazards worth naming."},"pocket-creek":{"boundary":"A steep tributary of the Sequatchie River in Marion County that falls off the Cumberland Plateau down the escarpment to the valley floor near Whitwell. The cold escarpment gorge fishes best in summer; the accessible lower valley reach fishes in the cool months.","points":[{"n":"The cold escarpment gorge","d":"The signature reach — steep, shaded, spring-fed plunge pools that hold the best holdovers."},{"n":"The mouth on the valley floor","d":"Where the creek reaches the Sequatchie Valley floor near Whitwell."},{"n":"The headwaters on the Plateau","d":"The cold high water up on the Cumberland Plateau caprock."}],"wf":"A steep wade up in the gorge, gentler over gravel and ledge on the valley floor; walk-in for the gorge.","note":"A steep escarpment creek that rises hard and fast over slick, dangerous rock; help is not close in the gorge and a cell signal is not guaranteed. Much of the valley reach is private."},"roan-and-doe-creek":{"boundary":"A linked pair of Johnson County valley streams — Doe Creek is a tributary of Roan Creek — draining the Mountain City valley into the Roan Creek embayment of Watauga Lake. TWRA stocks the cool upper reaches; the lower creeks are cool-to-warm water feeding the lake.","points":[{"n":"Upper Roan and upper Doe Creek","d":"The stocked, cool-season trout reaches of each creek."},{"n":"Roan Creek embayment of Watauga Lake","d":"The lower water and mouth where a spring walleye run stages."},{"n":"Doe Creek walleye-run reach","d":"Lower Doe Creek, Old Cabin Road down to the Roan Creek confluence, under the single-hook walleye rule."},{"n":"Roan Creek walleye-run reach","d":"Lower Roan Creek, the Mountain Lake Estates Bridge down to the Doe Creek confluence."}],"wf":"Small valley streams waded a pocket at a time up top; the lower water slows toward the lake.","note":"Small valley streams that come up and color fast after rain and drop just as quickly; a single-hook walleye-run rule applies to the lower reaches January 1 through April 30."},"rock-creek":{"boundary":"A steep Cherokee National Forest creek off Unaka Mountain east of Erwin, dropping more than three thousand feet in about five miles — stocked rec-area water down low near Erwin, wild-rainbow pocket water up high toward the Unaka crest.","points":[{"n":"Rock Creek Recreation Area","d":"The creekside campground and swimming area that is the base for a visit, on the stocked lower-middle creek."},{"n":"Lower reach at the edge of Erwin","d":"The bottom of the creek near town."},{"n":"Rock Creek Falls","d":"A landmark on the climb into the wild upper water."},{"n":"Wild upper pocket water","d":"Small, cold plunge pools and boulder pockets holding wild rainbows high on the Unaka flank."}],"wf":"Easy pool-and-run wading at the rec area; a steep walk-in to the wild upper creek.","note":"The steep upper water rises fast and turns slick and dangerous above the rec area — turn back on high water; cell coverage in the drainage is thin and bear-country precautions apply."},"rocky-fork":{"boundary":"A fast Blue Ridge freestone in the Rocky Fork tract near Erwin, running from the South Indian Creek confluence up through the state park's Main Entrance Gate into native brook-trout headwaters above roughly 3,000 feet. The lower roadside water below the gate is the open, stocked family water; the native headwaters are kept protected.","points":[{"n":"Lower roadside reach below the Main Entrance Gate","d":"The last roadside mile or so, seasonally stocked put-and-take family water fished under statewide rules."},{"n":"Main Entrance Gate","d":"The regulation boundary at the junction of Rocky Fork Road and the State Park Entrance Road, above which single-hook artificial-only wild-trout rules apply."}],"wf":"Wadeable when low or medium and clear; roadside below the gate, walk-in above.","note":"The native brook-trout headwaters are deliberately kept coarse — described by reach only, never pinpointed. A steep mountain freestone that rises hard and fast over slick boulder and bedrock; the upper reaches are remote with poor cell coverage in bear country — know your exit and turn back on a rising creek."},"slickrock-creek":{"boundary":"A remote, roadless wild-brown-trout creek in the Joyce Kilmer–Slickrock Wilderness on the Tennessee–North Carolina line, running from Calderwood Lake up past Lower Falls to Wildcat Falls. Native brook trout hold the coldest uppermost headwaters, which are left unmapped.","points":[{"n":"Slickrock Creek / Ike Branch trails","d":"The lakeside foot approach from U.S. 129 at the Calderwood Lake bridge, about two miles to the mouth and the big lower pools."},{"n":"Big Fat Gap Trail (FS 41)","d":"A steep trail dropping to the middle creek near the Nichols Cove Branch junction."},{"n":"Lower Falls barrier pool","d":"The signature barrier pool that stops upstream movement of lake fish, the most forgiving water on the creek."},{"n":"The mouth and big lower pools","d":"Deep lower pools holding fish moving up from Calderwood Lake."}],"wf":"A foot-access-only wilderness creek fished a pocket at a time; the Slickrock Creek Trail fords the creek thirteen times.","note":"The native brook-trout headwaters are deliberately left unmarked with no access. There is no reliable cell signal anywhere in the basin and you may be a day's walk from the trailhead — the fords turn dangerous after rain, so if the creek is high and pushy, turn around."},"south-indian-creek":{"boundary":"A limestone-influenced creek gathering off the Bald Mountains side of the Nolichucky valley near Erwin. The dependable public water is the Rocky Fork State Park gateway and confirmed roadside pull-offs; native brook trout in the cold high feeders are kept protected.","points":[{"n":"Rocky Fork State Park gateway","d":"The system's cold public heart, into the upper drainage via Rocky Fork Road off the Flag Pond area."},{"n":"Confirmed roadside pull-offs toward Spivey Gap","d":"The dependable valley-road public water in an otherwise private valley."},{"n":"Nolichucky mouth near Erwin","d":"Where the creek joins the Nolichucky opposite its sister, North Indian Creek."}],"wf":"A generally gentle gravel-and-cobble wade over slick limestone; roadside and gateway access, with a climb to the high feeders.","note":"The native brook-trout water in the high feeders is deliberately not published. The channel was rearranged by the historic 2024 flood — expect unstable logjams and collapsing banks, most of the valley is private, and cell coverage fails up in the high feeders, so go in daylight and tell someone your plan."},"stony-creek":{"boundary":"A Highway 91 valley freestone in northeastern Carter County running from the Cross and Iron Mountain divide down to the Watauga near Elizabethton — stocked, roadside water low, wilder pocket water high, with a lake-run bonus in the lowest holes.","points":[{"n":"Highway 91 pull-offs","d":"The roadside pull-offs that follow the creek up the valley."},{"n":"Blue Springs lower access","d":"A well-used lower access near the volunteer fire station at Blue Springs."},{"n":"The lower holes and the lake-run","d":"The signature reach where big lake-run rainbows and browns push up from the Watauga."},{"n":"Wild upper-mid water and headwaters near the divide","d":"The quieter wild brown and rainbow pocket water in the Cherokee National Forest."},{"n":"The mouth at the Watauga","d":"Where the creek joins the Watauga River near Elizabethton."}],"wf":"An easy roadside wade in the lower valley, rockier up high; the wild upper water asks for a little walking.","note":"A rain-fed freestone that rises fast and cold over slick rock; park fully off the highway, and note the lowest holes run higher and colder when the Watauga tailwater is generating."},"town-creek":{"boundary":"A short, gentle limestone creek on the floor of the lower Sequatchie Valley at Jasper, running from a short upper reach down to its mouth near the Sequatchie–Tennessee confluence. A cool-season stocked put-and-take water.","points":[{"n":"The mouth in the low valley","d":"The warm lower reach near the Sequatchie and Tennessee, where valley bass appear."},{"n":"The Jasper town reach","d":"The creek where it runs through the county seat."},{"n":"The cooler upper water","d":"The shaded, spring-influenced upper reach that holds trout longest."}],"wf":"An easy, gentle small-creek wade.","note":"A flashy freestone that rises and muddies fast after rain over slick limestone; it runs through town and private land at Jasper, so access must be earned by permission."},"trail-fork":{"boundary":"A steep, remote tributary falling off the Bald Mountains crest through the Cherokee National Forest of northern Cocke County to the Big Creek country. A completed native brook-trout restoration above a natural waterfall barrier, with general wild small-stream water below it.","points":[{"n":"The mouth in the Big Creek country","d":"The lower end of the creek in the Big Creek drainage."},{"n":"The forested mid reach","d":"General wild water below the barrier."},{"n":"The approach below the barrier","d":"The open public water up to, but not above, the waterfall barrier."}],"wf":"Small water fished a pocket at a time, reached only by miles of winding forest travel; a long backcountry walk-in.","note":"The native brook-trout restoration reach above the waterfall barrier is deliberately left unpinned. Remote, steep backcountry far from help with no reliable cell coverage — know your exit, and any Cherokee National Forest closure sign governs."},"upper-hills-creek":{"boundary":"The upper, stocked reach of Hills Creek, a small tributary of the Collins River in southeastern Warren County near the Warren–Grundy line, reached from McMinnville. A short, low-gradient Highland Rim limestone creek, stocked for the cool months.","points":[{"n":"The mouth at the Collins","d":"Where the creek meets the Collins and turns warmwater with smallmouth and rock bass."},{"n":"The stocked mid-reach","d":"The reach TWRA stocks with rainbows, the reason a fly angler comes."},{"n":"The cool headwaters toward the Grundy line","d":"The shaded, spring-influenced upper water that stays trout-friendly longest."}],"wf":"Small, gentle, low-gradient limestone water — wadeable in the cool season; not a plunge-pool mountain stream.","note":"A freestone that rises and muddies fast after hard rain over slick limestone; much of it crosses private farm ground with barbed wire and fences, so permission is required."},"wolf-creek":{"boundary":"A small, wild native-brook-trout freestone falling out of the Bald Mountains of Cocke County to the French Broad near Del Rio. The lower valley holds wild rainbows and browns; the native brook trout of the cold upper valley above the falls are kept unmapped by design.","points":[{"n":"The mouth on the French Broad near the Wolf Creek community","d":"The lower end of the creek at its French Broad confluence."},{"n":"The lower wild-rainbow water","d":"The more accessible lower reach holding wild rainbows and browns."},{"n":"Wolf Creek Falls","d":"A natural boundary on the creek and the general edge of the protected water."},{"n":"Round Mountain Recreation Area","d":"A verified public landmark up the drainage."},{"n":"Del Rio and Newport gateways","d":"The road gateways to the drainage from the French Broad valley and I-40."}],"wf":"A steep small freestone waded a pocket at a time; a walk-and-drive approach, with a climb to the cold headwaters.","note":"No route is published to the native brook-trout water above the falls. There is no cellular coverage anywhere in the valley — carry a satellite messenger, tell someone your plan and out-time; the creek rises fast on mountain rain over slick bedrock, on gated rough forest roads in bear country."}});
Object.assign(ACCESS,{"abrams-creek":{"boundary":"Abrams Creek runs roughly twelve miles entirely inside the park, from Cades Cove down to Chilhowee Lake, in Blount County on the Tennessee side; its alkaline limestone chemistry grows the largest-averaging wild rainbows in the park, with a remnant of browns. Below the campground it becomes smallmouth and rock bass water.","points":[{"n":"Abrams Falls Trailhead (Cades Cove Loop Road)","d":"The main way to the creek, off the one-way Cades Cove Loop Road."},{"n":"Abrams Creek Campground","d":"A second, more remote way in on the park's western edge."},{"n":"Abrams Falls","d":"A 35-foot drop of exceptional volume that has taken multiple lives; a place to look, not to test."},{"n":"The Horseshoe","d":"A mile-long backcountry loop on the most treacherous bedrock in the park; committing water that demands studded felt and an early start."}],"wf":"Wade-and-scramble freestone with a demanding, storied backcountry loop; the alkaline limestone is described as the most treacherous wading surface in the park.","note":"Rain-driven and rises hard and fast; the falls and the Horseshoe are life-safety hazards on the slickest rock in the park, cell service is absent in the gorge, and felt soles with studs are the minimum."},"anthony-creek":{"boundary":"Anthony Creek is the largest tributary of Abrams Creek, a small wadeable freestone draining the Bote Mountain and Spence Field ridgeline into Cades Cove, in Blount County; wild rainbows fill the lower reach and a restored native brook-trout population holds the upper 1.75 miles.","points":[{"n":"Cades Cove Picnic Area","d":"The single public trailhead and easy-parking base for the lower creek."},{"n":"Anthony Creek Trail","d":"Follows the lower creek up toward Spence Field; the wide trail makes this a teaching stream."},{"n":"Backcountry campsite #9","d":"A quiet base about 2.9 miles up for reaching the higher reaches."}],"wf":"Small, forgiving walk-in freestone off a wide trail — one of the best teaching and family streams in the park at the lower end, steepening backcountry above.","note":"Rain-fed and rises fast after storms over slick bedrock; cell coverage drops off fast climbing toward Spence Field, and felt soles with studs are the minimum. The restored brook-trout reach in the upper watershed is kept deliberately coarse."},"big-creek":{"boundary":"Big Creek is a wild-rainbow gorge stream in the far northeastern corner of the park, fished from the Tennessee gateway at Interstate 40's Exit 451 (Waterville) in Cocke County, though it rises across the line in Haywood County, NC. Native brook trout hold higher up and in the cold tributaries.","points":[{"n":"Big Creek area (I-40 Exit 451 / Waterville)","d":"The gateway with campground, horse camp, picnic area, and trailhead."},{"n":"Big Creek Trail (old Crestmont grade)","d":"An old railroad grade high above the water; reaching the stream is a rough scramble."},{"n":"Midnight Hole","d":"A deep plunge pool that is one of the park's busiest swimming holes; fish it early or around it."},{"n":"Mouse Creek Falls","d":"The signature reach landmark about two miles up the trail."},{"n":"Walnut Bottom","d":"The backcountry area about five miles up where the Swallow Fork and Gunter Fork trails branch off."}],"wf":"Wade-and-climb pocket water: a steep, boulder-strewn gorge reached by scrambling down from a trail that rides high above the stream.","note":"Steep gorge that rises fast and wades hard after rain; coverage is limited and thins fast in the gorge, and this is bear country with a long record of human-bear conflict — store food properly. The brook-trout feeders are kept coarse by design."},"bone-valley-creek":{"boundary":"Bone Valley Creek is a remote backcountry tributary of Hazel Creek on the North Carolina side in Swain County, entering Hazel at backcountry campsite #83 and reached only by boat across Fontana Lake plus a hike. The lower creek holds medium wild rainbows and the occasional brown; native brook trout hold the protected headwaters.","points":[{"n":"Bone Valley Trail","d":"Runs from the Hazel Creek confluence up past unbridged fords to the fishing and the Hall Cabin."},{"n":"The Hall Cabin","d":"The 1892 cabin at the end of the trail — the most remote historic structure in the park."},{"n":"Hazel Creek confluence (campsite #83)","d":"Where Bone Valley enters Hazel Creek; the trip's staging point."}],"wf":"Remote boat-in-and-hike backcountry freestone with repeated unbridged fords; a multi-day commitment.","note":"Remote backcountry with no cell service and help a long way off across the lake; the unbridged Bone Valley Trail fords dangerously high after rain, and this is dense black-bear country — know your exit. The native brook headwaters are kept coarse."},"bradley-fork":{"boundary":"Bradley Fork is a medium pocket-water stream that joins the Oconaluftee River at Smokemont Campground on the North Carolina side in Swain County, holding wild, never-stocked rainbow and brown trout in easy walk-in water; native brook trout hold the cold headwaters higher up.","points":[{"n":"Smokemont Campground","d":"The single trailhead and the confluence with the Oconaluftee; family- and beginner-friendly water at the bottom."},{"n":"Bradley Fork Trail (old railroad grade)","d":"A nearly flat old railroad grade that follows the creek seven miles into the backcountry."},{"n":"Chasteen Creek Cascade","d":"The landmark of the lower creek, a short way up the trail."}],"wf":"Easy, near-flat walk-in wading at the bottom on a railroad-grade trail, growing more committing the deeper up the drainage you go.","note":"Rain-fed freestone that rises hard and fast after a storm over slick rock; coverage is workable near Smokemont but falls away up the drainage into the backcountry. The cold upper headwaters are kept coarse."},"cataloochee":{"boundary":"Cataloochee Creek is the park's remote northeastern valley on the North Carolina side in Haywood County — a slow, clear, meadow-bottomed freestone reached only by the long gravel Cove Creek Road. It holds wild, never-stocked trout, mostly rainbows with a few browns generally under ten inches, with native brook trout in the cold upper feeders. This is the park's elk valley.","points":[{"n":"Cove Creek Road","d":"The long, winding gravel road in from the Jonathan Creek / Maggie Valley side off I-40; the difficulty keeps pressure light."},{"n":"The meadow reach","d":"Open, slow, clear valley water where the fish are exceptionally wary and the approach is everything."},{"n":"Palmer Creek and Caldwell Fork","d":"The main tributaries entering the valley; the tributary mouths hold fish."},{"n":"Palmer Chapel and the Caldwell House","d":"Preserved historic structures standing in the meadows you fish through."}],"wf":"Wadeable open meadow freestone, best low-to-normal and clear, where stealth beats casting.","note":"Remote valley with limited to no cell service on the approach and a long committing gravel road; it is the park's elk valley — stay at least 50 yards back — and as of mid-2026 is still recovering from Hurricane Helene with the road impassable beyond Pretty Hollow Gap and several trails closed. Confirm current NPS road and trail status. The native brook trout in the upper feeders are kept coarse."},"cosby-creek":{"boundary":"Cosby Creek is a small, tight stream in the quiet northeast corner of the park above the community of Cosby in Cocke County, TN. The lower, road-accessible water below Cosby Campground holds small wild rainbows; native brook trout begin almost at the campground and climb the tight headwater feeders toward the state-line ridge.","points":[{"n":"Cosby Campground","d":"The quiet, uncrowded base; fish downstream for rainbows. It sits essentially on the brook-trout boundary."},{"n":"Lower roadside creek","d":"Small willing rainbows on easy roadside water — one of the best beginner and family venues in the park."},{"n":"Mt. Cammerer stone lookout","d":"The restored octagonal native-stone fire tower on the ridge above the headwater brook water."}],"wf":"Small, wadeable but flashy roadside freestone below the campground; tight, lonely native-brook headwater climbing above it.","note":"Rises fast after a mountain storm over slick, mossy rock; coverage is unreliable and gone as you climb, and this is dense black-bear country — store food properly. The brook-trout headwaters are kept deliberately coarse."},"deep-creek":{"boundary":"Deep Creek drains the park's southern slope toward Bryson City in Swain County, NC — big water by Smokies measure and the finest brown-trout stream on the North Carolina side, reached through the Deep Creek entrance and campground. It holds an even mix of wild rainbow and wild brown trout, with native brook trout in the highest headwaters.","points":[{"n":"Deep Creek entrance and campground","d":"The way in, just north of Bryson City."},{"n":"Deep Creek Trail and Indian Creek Trail","d":"Carry up the drainage and its tributaries into the brown-trout water."},{"n":"Indian Creek tubing take-out","d":"Walk above it and the big brown-trout water opens up; below it is a busy summer tubing run."},{"n":"The falls string (Tom Branch, Indian Creek, Juney Whank)","d":"The signed lower-creek falls the drainage is known for."}],"wf":"Big-by-park-measure wadeable freestone — long riffled runs, deep green pools, and heavy pocket water; walk above the tubing reach for the trout water.","note":"Flashy freestone that rises hard and fast after rain over slick rock; never climb on the falls, coverage disappears above the lower creek, and the lower mile is a busy summer tubing run — fish early or off-season. The brook-trout headwaters are kept coarse."},"eagle-creek":{"boundary":"Eagle Creek is a lightly fished wild-trout creek in the southwestern corner of the park on the North Carolina side, over Jenkins Trail Ridge west of Hazel Creek, reached only by boat across Fontana Lake to its mouth. Wild rainbows run its length, browns hold the lower water, native brook trout climb the headwaters, and early spring brings lake-run rainbows up from Fontana.","points":[{"n":"The mouth on Fontana Lake","d":"The boat-in landing where you step off to fish; there is no road to the creek."},{"n":"Cable Cove boat ramp","d":"A public ramp off Highway 28 for the lake crossing."},{"n":"Eagle Creek Trail","d":"Follows the creek up the valley and fords it repeatedly at unbridged crossings."}],"wf":"Remote boat-in backcountry freestone; moving up the water means repeated unbridged fords, a multi-day trip.","note":"Remote backcountry with no cell service and help a long way off across the lake; the trail's unbridged fords turn dangerous fast on rising water, and this is dense black-bear country — store and hang all food. The native brook headwaters are kept coarse."},"forney-creek":{"boundary":"Forney Creek is a large, remote backcountry watershed on the North Carolina side over Welch Ridge east of Hazel Creek, falling to Fontana Lake in the park's southwestern corner in Swain County. Reached by boat across Fontana or the long walk in through the 'Road to Nowhere' tunnel, it holds eager wild rainbows through the main creek and tributaries, wild browns in the lower water, and protected native brook trout up high.","points":[{"n":"'Road to Nowhere' (Lakeview Drive) trailhead and tunnel","d":"The long walk-in route near Bryson City; the road dead-ends at a tunnel and the trail picks up beyond it."},{"n":"Fontana Lake crossing","d":"The boat-in approach to the remote watershed."},{"n":"Forney Creek Trail","d":"Climbs the valley beside the water but crosses the creek repeatedly at unbridged fords."}],"wf":"Remote boat-in and walk-in backcountry freestone; the trail fords the creek repeatedly with no bridges, a committing multi-day trip.","note":"Remote backcountry with no reliable cell coverage and help a long way off; the fords turn impassable and dangerous after an afternoon storm, and it is serious black-bear country — hang all food. The native brook headwaters are kept coarse."},"goshen-prong":{"boundary":"Goshen Prong is a small, high, cold headwater of the Little River in Sevier County, reached only by about a seven-mile walk above Elkmont, climbing toward Silers Bald and the Appalachian Trail. Lower Goshen and the mouths hold wild rainbows; the high, cold water above holds native Southern Appalachian brook trout.","points":[{"n":"Little River Trail (from Elkmont)","d":"The old railway-grade approach, about 3.7 miles up to the Goshen Prong Trail."},{"n":"Backcountry campsite #23","d":"The only sensible base, near the Fish Camp Prong confluence, before Goshen climbs in earnest."},{"n":"The climb to Silers Bald","d":"Above #23 the trail curves southeast and climbs toward the Appalachian Trail and Silers Bald."}],"wf":"Committing hike-in backcountry: small, rocky, high headwater fished as a reserved two-day trip from campsite #23, not a day trip.","note":"Remote backcountry with no cell service seven miles in and help a long way off — tell someone your plan and know your out; flashy over wet, moss-slick rock, cold enough for hypothermia in any season, and dense black-bear country. The native brook-trout headwaters are held back deliberately."},"greenbrier":{"boundary":"Greenbrier is the valley of the Middle Prong of the Little Pigeon River, reached six miles east of Gatlinburg in Sevier County via the park's least-used Tennessee gateway. Big-boulder freestone with wild rainbows the length of the corridor, wild browns in the deeper pools below the picnic area, and native brook trout up the cold Porters Creek and Ramsey Prong headwaters.","points":[{"n":"Greenbrier Road corridor","d":"A short road (paved first mile, then gravel) of riverside pullouts; big pocket water fished straight off the shoulder."},{"n":"Greenbrier Ranger Station","d":"Where the gravel begins; the closest place to buy a parking tag, and where cell service ends."},{"n":"The picnic area (third mile)","d":"The big-boulder plunge-pool water below it is the signature reach."},{"n":"Porters Creek and Ramsey Prong trailheads","d":"The fork at the head of the cove leading toward Ramsey Cascades and the Porters Flat homesteads."}],"wf":"Big-boulder freestone fished off the road shoulder in the corridor, with native-brook backcountry a walk away at the head of the cove.","note":"Rises fast and hard after mountain storms over slick rock; wading among house-sized boulders is the real hazard, cell service drops out past the ranger station, and road/trail status can change after flooding — check current NPS closures. The native brook headwaters of upper Porters and Ramsey are protected water kept coarse."},"hazel-creek":{"boundary":"Hazel Creek is roughly fifteen miles of cold, clear wild water on the North Carolina side in Swain County, the most storied trout stream in the Smokies, reached by crossing Fontana Lake by boat and fished over days from a backcountry camp among the ruins of Proctor. Big wild browns hold the lower pools, rainbows fill its length, and native brook trout climb the high headwaters above the Hazel Creek Cascades.","points":[{"n":"Fontana Village Marina ferry shuttle","d":"The standard approach, stepping you off at the mouth just below Proctor."},{"n":"Cable Cove boat ramp","d":"A public ramp off Highway 28 for the lake crossing."},{"n":"Hazel Creek Trail (old Calico Street)","d":"The flat lower grade climbing fifteen miles with frequent stream access."},{"n":"Proctor / Calhoun House","d":"The ghost-town townsite and 1928 Calhoun House near campsite #86; the valley's history."},{"n":"The Brown Hole","d":"A famous deep lower-creek pool holding the big wild browns."}],"wf":"Remote boat-in backcountry with a flat, easy fifteen-mile streamside trail; fished best as a multi-day trip from a backcountry camp.","note":"Remote roadless backcountry with no cell service and help across the lake; a flashy freestone that rises fast over slick rock, and serious black-bear country — hang all food on the bear cables. The high brook-trout headwaters are kept coarse."},"laurel-creek":{"boundary":"Laurel Creek is a small, quick roadside stream — the West Prong of the Little River's main tributary — running along Laurel Creek Road between the Townsend Wye and Cades Cove in Blount County, TN. Wild rainbows fill it, with native brook trout only in the highest, coldest headwater feeders.","points":[{"n":"Laurel Creek Road pullouts","d":"The creek is picked up easily from pullouts along the only paved road into Cades Cove; fish upstream at first light."},{"n":"Lower roadside water","d":"Small, willing wild rainbows most people drive straight past on the way to the Cove."},{"n":"Bee Cove Creek","d":"A smaller feeder joining lower down."}],"wf":"Small, wadeable roadside pocket water fished on the way to somewhere else; a genuine wild-trout creek, not a trophy stream.","note":"Rain-fed and flashy, rising fast after a storm over slick rock; low in elevation, the lower water warms and slows in midsummer, and cell coverage along the corridor is patchy. The native brook trout in the upper feeders are kept coarse."},"leconte-creek":{"boundary":"LeConte Creek is a small, steep freestone dropping off Mt. LeConte to the edge of Gatlinburg in Sevier County, TN, reached from the Cherokee Orchard area before the one-way Roaring Fork Motor Nature Trail. The lower, roadside reaches hold wild rainbows; native brook trout hold the headwaters. Rainbow Falls, the park's highest single-drop falls, is on this creek.","points":[{"n":"Cherokee Orchard area","d":"The access; park before the one-way loop and fish the open lower stretch upstream."},{"n":"Lower open water","d":"One to two hours of quality roadside pocket water holding educated wild rainbows."},{"n":"Rainbow Falls / Rainbow Falls Trail","d":"The trail (about 5.4 miles round trip) climbs the creek to Rainbow Falls, the park's highest single-drop falls at about eighty feet — a genuine hazard, not just a landmark."},{"n":"Noah 'Bud' Ogle Place","d":"An 1880s cabin with a streamside tub mill and flume on Cherokee Orchard Road just before the loop."}],"wf":"Small, wadeable roadside pocket water in the lower reaches; tight, brushy, boulder-strewn water toward the headwaters.","note":"Small and flashy, rising fast after rain over slick rock; never climb on Rainbow Falls or its wet ledges — people die on the Smokies' cascades — and coverage falls off climbing toward the falls. The native brook headwaters are kept coarse."},"little-river":{"boundary":"The East Prong of the Little River in Great Smoky Mountains National Park on the Tennessee side, running roughly thirteen miles of road-accessible water along Little River Road from the Townsend Wye up to Elkmont, then about six more miles of trail into the backcountry above.","points":[{"n":"Townsend Wye","d":"The downstream gateway where warmer, slower water mixes trout with smallmouth and rock bass."},{"n":"The Sinks / Little River Gorge","d":"A dramatic cascade and plunge pool that is the river's signature landmark and a busy summer swimming hole, not a place to climb."},{"n":"Metcalf Bottoms flats","d":"Smooth spring-creek-like pools over an algae-slick limestone slab where felt soles are mandatory."},{"n":"Elkmont","d":"A former logging town and resort community, now the premier riverfront base and the start of the backcountry trail."},{"n":"Little River Trail (above Elkmont)","d":"A reclaimed railway grade carrying six-plus miles of walk-in water into the backcountry."}],"wf":"Roadside wade water for thirteen miles along Little River Road, transitioning to walk-in backcountry on the Little River Trail above Elkmont.","note":"Rain-fed freestone that rises hard and fast after mountain storms over slick rock; cell service ends once you leave the main road, and this is dense black-bear country above Elkmont. Native brook-trout headwaters above the backcountry campsites are kept deliberately coarse."},"lynn-camp-prong":{"boundary":"The left fork at the head of the Tremont drainage on the Townsend (Tennessee) side of the park; the fishable, restored native brook-trout water is up the Middle Prong Trail above the Lynn Camp Prong Cascades, kept deliberately general.","points":[{"n":"Middle Prong Trailhead footbridge","d":"The road-end metal footbridge where the trail up the prong begins."},{"n":"Lynn Camp Prong Cascades","d":"The much-photographed cascades that form the natural barrier below the restored reach."}],"wf":"Walk-in from the road-end footbridge up the Middle Prong Trail; the brook water begins above the cascades and is kept coarse by design.","note":"A restored native brook-trout stream (closed 2008, reopened 2015) — exactly where the fishing begins above the barrier and the brook-specific detail are reserved for the non-commercial atlas; Indian Flats Prong, off Lynn Camp, is closed for restoration. Rain-driven and flashy over slick, mossy rock; coverage up the Tremont drainage is unreliable and likely gone above the cascades."},"middle-prong-tremont":{"boundary":"The valley of the Middle Prong of the Little River on the Tennessee side, reached from the Townsend Wye, running about six miles up one dead-end road to the footbridge at the prongs (Lynn Camp and Thunderhead); wild rainbow throughout, larger browns low, restored native brook up top.","points":[{"n":"Townsend Wye","d":"The busy swimming-and-tubing hole and the drainage's mouth, gateway to the road up."},{"n":"Lower paved reach","d":"The first paved couple of miles holding the drainage's largest browns and an occasional smallmouth in bigger, warmer pools."},{"n":"Great Smoky Mountains Institute at Tremont","d":"The last restrooms and the point past which cell coverage drops off."},{"n":"Gravel rainbow pocket water","d":"Where the pavement turns to gravel, the crowds thin and willing wild-rainbow pocket water begins."},{"n":"Road-end Middle Prong Trailhead","d":"The footbridge that splits the fishing — Thunderhead's rainbows right, Lynn Camp's protected brook water left."}],"wf":"One dead-end road follows the river its whole length — roadside wade water from the Wye up the paved and gravel reaches, then walk-in above the road-end footbridge.","note":"Rain-driven Smokies freestone that rises hard and fast after storms over slick rock; coverage thins climbing into the gorge and up the prongs, and this is dense black-bear country. Lynn Camp's restored native brook water is treated in coarse outline only; Sams Creek (off Thunderhead) and Indian Flats Prong are closed for restoration."},"noland-creek":{"boundary":"A wild North Carolina backcountry stream in Swain County, dropping off Noland Divide under Kuwohi (Clingmans Dome) down to an arm of Fontana Lake; wild rainbows in the lower, more accessible water give way to native brook trout climbing toward the headwaters.","points":[{"n":"Lakeview Drive / 'Road to Nowhere' trailhead","d":"The walk-in trailhead and tunnel near Bryson City where anglers enter the valley on foot."},{"n":"Lower Noland Creek","d":"The lower, more accessible water that holds the everyday wild-rainbow fishing."}],"wf":"Backcountry walk-in only — a long hike from the Lakeview Drive trailhead (or by boat across Fontana and the long trails in), with several unbridged crossings.","note":"Remote backcountry freestone that rises fast after rain; the unbridged crossings turn dangerous on rising water, there is no cell signal, and help is a long way off — know your exit before you walk in. Where rainbow water turns to native brook headwater is kept coarse."},"oconaluftee":{"boundary":"The in-park reach of the Oconaluftee on the park's North Carolina slope near Cherokee (Swain County), followed by Newfound Gap Road (US-441) from near Smokemont down toward the boundary; wild rainbow the length of the river with a smaller run of larger wild browns. This page covers only the park water above the boundary.","points":[{"n":"Smokemont / Bradley Fork confluence","d":"The upper roadside water where Bradley Fork joins at the campground and the bigger browns hold near first and last light."},{"n":"Newfound Gap Road (US-441) pulloffs","d":"Numerous roadside pulloffs give easy access to canopied, largely easy-wading pools and riffled runs."},{"n":"Mingus Mill","d":"The historic grist mill preserved near the lower park reach, a landmark of the lower browns water."}],"wf":"Roadside, largely easy wading along US-441 — a river of pools and riffled runs from Smokemont down toward the park boundary.","note":"Park freestone that rises hard and fast after mountain storms with no dam and no gauge on the river; where it leaves the park at Cherokee it becomes tribal Enterprise Water on the Qualla Boundary requiring a separate EBCI permit — a state license is not valid there. The native brook headwater feeders are kept coarse."},"porters-creek":{"boundary":"A headwater tributary at the very head of Greenbrier Cove on the Tennessee side (Sevier County), about six miles east of Gatlinburg; the Porters Creek Trail climbs about 3.7 miles up the cove. Willing wild rainbows in the accessible lower creek give way to protected native brook water higher up.","points":[{"n":"Porters Creek Trail (road's-end trailhead)","d":"The walk-in trailhead where Greenbrier Road ends, starting as an old gravel road up the cove."},{"n":"Porters Flat homesteads","d":"Stone walls, terraces, and standing chimneys of the farms that worked the head of the cove before the park."},{"n":"Messer Barn","d":"The signature landmark of the lower-trail walk at Porters Flat."},{"n":"Fern Branch Falls","d":"A cascade at about two miles up the trail — not a place to climb."},{"n":"Campsite #31 (Porters Flat)","d":"The backcountry site at trail's end anchoring the Greenbrier headwaters."}],"wf":"Small walk-in pocket water off a single road's-end trailhead; the lower creek is the accessible fishing and the trail steepens toward the protected headwaters.","note":"Flashy park freestone that rises fast and hard over slick rock — the July 2022 flood closed parts of the road and trail (confirm current status); cell service drops out past the Greenbrier Ranger Station, and this is dense black-bear country. The upper-Porters native brook water is kept coarse."},"ramsey-prong":{"boundary":"A wild headwater tributary of the Middle Prong of the Little Pigeon at the top of Greenbrier Cove (Sevier County), reached by the left fork past the Greenbrier Picnic Area; wild rainbows in the lower prong, native brook trout in the cold headwaters. It is walk-in backcountry, not roadside pocket water.","points":[{"n":"Greenbrier Picnic Area / scenic bridge fork","d":"The fork past the picnic area where the left fork toward Ramsey begins."},{"n":"Ramsey Prong Road","d":"About a mile and a half of gravel road to the Ramsey Cascades trailhead."},{"n":"Ramsey Cascades trailhead","d":"The large gravel lot where the strenuous walk-in trail up the prong begins."}],"wf":"A short gravel-road approach to the trailhead, then a strenuous walk-in — the fishable prong is entirely on foot up a steep, long trail.","note":"Ramsey Cascades — roughly a hundred feet, the tallest falls in the park — is a documented fatality site; never climb the cascades or the wet rock. There is no cell service past the Greenbrier Ranger Station, it is remote black-bear country, and the July 2022 flood damaged the road and trail (confirm status). The protected brook headwaters are described only in outline."},"raven-fork":{"boundary":"The upper, park-backcountry Raven Fork on the park's North Carolina slope, reached in from Straight Fork off the Balsam Mountain area; wild rainbow and native brook trout, fishable only up to Big Pool (the Three Forks confluence) — the park closes Raven Fork above Big Pool to protect native brook trout. This is NOT the stocked Cherokee tribal trophy tailwater of the same name, which is separate Qualla Boundary water requiring a Cherokee permit.","points":[{"n":"Straight Fork Road (Round Bottom Road)","d":"The one-way in-park road off Balsam Mountain where Big Cove Road meets the park and the approach begins."},{"n":"Straight Fork","d":"The in-park tributary giving small-stream rainbow fishing from the hatchery up to Round Bottom."},{"n":"Million Dollar Bridge","d":"The point above which water turns to small wild rainbow mixed with native brook trout, with a maintained trail a short way before the backcountry begins."},{"n":"Big Pool (Three Forks confluence)","d":"The upper limit of fishable water; the forks above are closed to protect native brook trout."}],"wf":"Expert-only, off-trail backcountry expedition — a long hike in from Straight Fork past the Million Dollar Bridge toward Big Pool; not a day trip.","note":"One of the most remote and committing reaches in the park: a flash-flood-prone gorge, no cell service, dense black-bear country, hours from help — go only with a partner, a plan, and a known out-time, and fish only up to the Big Pool closure. The lower Cherokee tribal trophy tailwater is a separate fishery under EBCI permit."},"road-prong":{"boundary":"A tight, technical headwater tributary of the West Prong of the Little Pigeon (Sevier County, TN side), climbing about three miles off Newfound Gap Road on the old Indian Gap route to meet Walker Camp Prong under the Chimney Tops; small wild rainbows low, native brook trout up top.","points":[{"n":"Chimney Tops parking area","d":"The Newfound Gap Road trailhead where the walk-in Road Prong Trail leaves the highway."},{"n":"Road Prong Trail","d":"The historic Indian Gap route climbing roughly three miles of tight headwater water toward the gap — awkward at the bottom, better as you climb."}],"wf":"A single walk-in headwater off the Chimney Tops parking area; wading is strenuous among the boulders and plunge pools.","note":"Steep park freestone that rises fast after rain over slick, mossy rock — never climb the waterfalls; cell coverage fades to none climbing the upper trail. The native brook water up high is kept coarse; confirm whether Road Prong is on the current restoration closed-waters list."},"roaring-fork":{"boundary":"A small, steep freestone off the flank of Mt. LeConte at the Gatlinburg gateway (Sevier County), followed by the one-way Roaring Fork Motor Nature Trail; wild rainbows in the lower accessible water, native brook trout climbing into the headwaters.","points":[{"n":"Roaring Fork Motor Nature Trail","d":"A narrow one-way scenic loop running right alongside the water with sixteen numbered auto-tour stops."},{"n":"Noah 'Bud' Ogle Place","d":"An 1880s cabin with a streamside tub mill and flume on a short nature trail just before the loop."},{"n":"Grotto Falls / Trillium Gap trailhead","d":"The trailhead to the only park waterfall you can walk behind, on Roaring Fork itself."},{"n":"Place of a Thousand Drips","d":"A rain-fed cascade running right beside the road near the lower end of the loop."}],"wf":"Roadside wade water — tight, brushy, boulder-strewn pocket water tucked between the auto-tour stops along the one-way motor trail.","note":"Steep freestone that rises fast after rain over slick, mossy rock — never climb the falls; the one-way motor trail closes in winter (typically open only about mid-April to late November), and the lower reaches saw the 2016 Chimney Tops 2 fire. The native brook water up high is kept coarse."},"sams-creek":{"boundary":"A small, cold native brook-trout headwater — a tributary of Thunderhead Prong high in the Tremont drainage on the Tennessee side — that is CLOSED to all fishing for active native Southern Appalachian brook-trout restoration. It is on the site for its story and conservation, named but not mapped, not as a place to fish.","points":[],"wf":"Not applicable — Sams Creek is a closed, posted restoration reach; the right relationship to it is distance. Fish the open water nearby (Lynn Camp Prong, or Thunderhead Prong below the Sams confluence) instead.","note":"Closed to all fishing while it heals — do not cast on it or wade it to 'just look'; keep its locations coarse and honor the posted restoration closure. Closed-waters lists shift season to season, so confirm the current one."},"sugar-fork":{"boundary":"A wild-rainbow tributary of Hazel Creek deep in the North Carolina backcountry (Swain County), the first major tributary above Proctor, entering near campsite #84 at the old settlement of Medlin about five miles up the valley; native brook trout hold in the protected upper feeders.","points":[{"n":"Hazel Creek boat drop (Fontana Lake)","d":"The lake crossing — public ramp at Cable Cove or the Fontana Village Marina shuttle — that is the only way in, stepping off below Proctor."},{"n":"Hazel Creek Trail","d":"The roughly five-mile hike from the boat drop up to the Sugar Fork confluence, with unbridged crossings."},{"n":"Campsite #84 / old Medlin","d":"The backcountry camp at the Sugar Fork–Hazel confluence — Horace Kephart's ground — that anchors a multi-day trip."}],"wf":"Deep backcountry: a boat crossing of Fontana Lake plus a five-mile hike up Hazel Creek, fished as a multi-day trip from a backcountry camp.","note":"Remote, flashy freestone with no cell service and no nearby help — a long way in across the lake in serious black-bear country; every backcountry night needs a permit and reservation and non-optional bear-cable food discipline. The native brook headwaters are kept coarse."},"thunderhead-prong":{"boundary":"The right-hand wild-rainbow fork at the top of the Tremont valley (Blount County, TN side), reached on foot up the old Defeat Ridge manway from the road-end Middle Prong Trailhead; small tumbling pocket water broken by deep plunge pools, fishable below the Sams Creek confluence.","points":[{"n":"Middle Prong Trailhead footbridge","d":"The road-end parking and metal footbridge at the confluence of Lynn Camp and Thunderhead prongs."},{"n":"Defeat Ridge manway (right fork)","d":"The old railroad-and-manway grade up the right fork that carries the walk-in fishing."},{"n":"Sams Creek confluence","d":"About a mile up, the upper practical limit — fish Thunderhead below it and leave closed Sams Creek alone."}],"wf":"Walk-in fishing off an old railroad-and-manway grade from the road's end; above the Sams Creek confluence an angler is in genuine backcountry.","note":"Small, flashy freestone that rises fast after mountain rain over slick rock; no cell service past the trailhead, dense black-bear country, and the last gravel miles of Upper Tremont Road close in winter weather. Sams Creek (about a mile up) is closed to all fishing for brook-trout restoration."},"twentymile-creek":{"boundary":"The park's far southwestern corner in North Carolina (Swain County) — a medium freestone gathering off Shuckstack Mountain and running about four to six miles down to Cheoah Lake below Fontana Dam; wild rainbows are the whole show, a rare brown turns up low, and there are essentially no brook trout.","points":[{"n":"Twentymile Ranger Station","d":"The often-unoccupied station right at the park entrance off NC-28, a measure of how little pressure this corner sees."},{"n":"Twentymile Trail","d":"The trail that shadows the creek upstream (part of the Benton MacKaye Trail) past the cascade side path toward the tower."},{"n":"Shuckstack fire tower","d":"The landmark and overlook of the watershed at the top of the long climb, where the trail ties into the Appalachian Trail."}],"wf":"Walk-in wade water — a small lot above the ranger station off NC-28, then the Twentymile Trail shadowing the creek; wade up the streambed where rhododendron closes in.","note":"Flashy Smokies freestone that rises hard after rain over slick rock; a remote corner with limited, unreliable cell coverage and dense black-bear country — come prepared and self-sufficient. Fontana Dam sits at the mouth but does not control the creek."},"west-prong-little-pigeon":{"boundary":"The in-park reach of one of the largest streams in the park (TN side), following Newfound Gap Road (US-441) from the Chimney Tops down through Sugarlands toward Gatlinburg; big boulder-and-pocket wild-rainbow water, browns in the deeper pools, native brook trout up high. Below Sugarlands it becomes Gatlinburg city-managed water covered elsewhere.","points":[{"n":"Newfound Gap Road (US-441) pullouts","d":"Numerous roadside pullouts between Sugarlands and the Chimney Tops giving quick access to big wild pocket water."},{"n":"Sugarlands","d":"The lower corridor gateway (visitor center) below which the stream leaves the park into Gatlinburg city water."},{"n":"Chimney Tops / Walker Camp & Road Prong forks","d":"The high headwaters where Walker Camp Prong and Road Prong meet to form the West Prong."}],"wf":"Roadside but strenuous wading — big boulders and plunge pools along the US-441 pullouts, with walk-in tributaries (Road Prong) climbing off the road.","note":"Big-boulder freestone that rises fast after rain over slick rock — never climb the waterfalls; coverage thins climbing toward the Chimney Tops and drops off entirely up Road Prong, and this is dense black-bear country. The native brook water above roughly 3,000 feet is kept coarse."}});
function afCSS(){if(document.getElementById('af-css'))return;var s=document.createElement('style');s.id='af-css';s.textContent='.af-bound{margin:6px 0 12px}.af-pts{margin:8px 0 6px}.af-pt{padding:9px 0;border-top:1px solid #ece3cd}.af-pt:first-child{border-top:none}.af-pt .af-n{color:#1B3A5C;font-weight:bold}.af-wf{margin:12px 0 4px}.af-note{font-size:13.5px;color:#6a7a86;border-left:3px solid #C8791E;padding:6px 12px;margin:12px 0 2px;background:#fbf4e6}.af-paid{margin:14px 0 2px;padding-top:10px;border-top:1px solid #e5dcc4;font-size:14px}';document.head.appendChild(s);}
