function gaugeCard(w){var g=w.gauge;if(!g)return readWater();var card=el('div','gauge');var left=el('div','rd');
 if(g.live){left.innerHTML='<span class="liveblob"></span><span class="lbl">Live flow · '+g.name+'</span><div><span class="num" id="g-cfs">…</span> <span class="lbl">cfs</span> &nbsp; <span class="num" id="g-ht" style="font-size:20px">…</span> <span class="lbl">ft gage</span></div><div class="asof" id="g-asof">fetching latest USGS reading…</div>';}
 else{left.innerHTML='<span class="lbl">Flow &amp; conditions · '+g.name+'</span><div class="asof">No real-time USGS feed on this gauge — open the official page for stage/schedule.</div>';}
 card.appendChild(left);card.appendChild(el('div','spacer'));var b=el('a','btn btn-ghost btn-sm','Open USGS gauge ↗');b.href=usgsUrl(g.id);b.target='_blank';b.rel='noopener';card.appendChild(b);return card;}
async function hydrate(w){if(!w.gauge||!w.gauge.live)return;try{var u='https://waterservices.usgs.gov/nwis/iv/?format=json&sites='+w.gauge.id+'&parameterCd=00060,00065&siteStatus=all';var r=await fetch(u);var j=await r.json();var cfs=null,ht=null,when=null;(j.value.timeSeries||[]).forEach(function(ts){var c=ts.variable.variableCode[0].value;var v=ts.values[0].value;if(!v||!v.length)return;var last=v[v.length-1];if(c==='00060'){cfs=last.value;when=last.dateTime;}if(c==='00065'){ht=last.value;when=when||last.dateTime;}});var cE=document.getElementById('g-cfs'),hE=document.getElementById('g-ht'),aE=document.getElementById('g-asof');if(cE)cE.textContent=cfs!=null?Number(cfs).toLocaleString():'n/a';if(hE)hE.textContent=ht!=null?Number(ht).toFixed(2):'n/a';if(aE)aE.textContent=when?('as of '+new Date(when).toLocaleString()+' · source USGS '+w.gauge.id):'source USGS '+w.gauge.id;}catch(e){var aE=document.getElementById('g-asof');if(aE)aE.textContent='Live reading unavailable right now — tap “Open USGS gauge” for the official page.';var cE=document.getElementById('g-cfs'),hE=document.getElementById('g-ht');if(cE)cE.textContent='—';if(hE)hE.textContent='—';}}
function damBar(w){var bar=el('div','resbar');var a=el('a','btn btn-primary btn-sm',w.dam.label+' ↗');a.href=w.dam.url;a.target='_blank';a.rel='noopener';bar.appendChild(a);if(w.dam.phone){var p=el('a','btn btn-ghost btn-sm',w.dam.phoneLabel);p.href=tel(w.dam.phone);bar.appendChild(p);}return bar;}
